// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address newOwner = address(0x123);
        address admin = address(this); // deployer is admin
        vm.prank(admin);
        c.setOwner(newOwner);
        // Reference: owner becomes newOwner; mutant: owner stays as admin (address(this))
        assertTrue(c.owner() == newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // The default admin is the deployer (address(this)). Call setOwner as admin.
        // After calling, the return value should be true in the correct contract.
        bool result;
        // We use a try-catch to safely capture the boolean return value.
        try this.callSetOwner(address(0x123)) returns (bool r) {
            result = r;
        } catch {
            result = false;
        }
        assertTrue(result, "setOwner should return true on the correct contract");
    }
    // Helper to call setOwner on c so we can capture the return value
    function callSetOwner(address _newOwner) external returns (bool) {
        return c.setOwner(_newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address newOwner = address(0x123);
        address admin = address(this);

        vm.prank(admin);
        c.setOwner(newOwner);

        // In the reference, owner == newOwner; in the buggy, owner == admin.
        assertTrue(c.owner() == newOwner);
    }
}
